public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // check if the starting and ending n-tersections are valid
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n ||
        end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        return "cannot be travelled";
    }

    // perform a breadth-first search to find the shortest path between the starting and ending n-tersections
    Queue<int[]> queue = new LinkedList<>();
    queue.add(start);
    int[][] visited = new int[n][n];
    while (!queue.isEmpty()) {
        int[] current = queue.remove();
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }
        for (int[] neighbor : getNeighbors(current, paths)) {
            if (visited[neighbor[0]][neighbor[1]] == 0) {
                visited[neighbor[0]][neighbor[1]] = 1;
                queue.add(neighbor);
