public int minTime(int n, int[][] edges, boolean[] hasApple) {
  if (n == 0 || edges.length == 0 || hasApple.length == 0) {
    return 0;
  }
  // Create a graph with n nodes and edges
  Graph graph = new Graph(n);
  for (int[] edge : edges) {
    graph.addEdge(edge[0], edge[1]);
  }
  // Perform Breadth-First Search (BFS) from node 0
  Queue<Integer> queue = new LinkedList<>();
  queue.offer(0);
  boolean[] visited = new boolean[n];
  int time = 0;
  while (!queue.isEmpty()) {
    int node = queue.poll();
    if (!visited[node]) {
      visited[node] = true;
      time++;
      if (hasApple[node]) {
        return time;
      }
      for (int neighbor : graph.getNeighbors(node)) {
        if (!visited[neighbor]) {
          queue.offer(neighbor);
        }
      }
    }
  }
  return time;
}

