public static int minPerfectSquareSum(int n) {
    int minSquares = 0;
    while (n > 0) {
        int root = (int) Math.sqrt(n);
        if (root * root == n) {
            minSquares++;
            break;
        } else {
            minSquares++;
            n -= root * root;
        }
    }
    return minSquares;
}
